#!/usr/bin/env node
/**
 * Southbank S&C - Automated Class Booking
 *
 * Logs in, finds the target class, and books it via the GraphQL API.
 * Uses cookie-based auth (httpOnly cookies handled by fetch with cookie jar).
 *
 * Usage:
 *   node book-class.mjs                    # Book next Monday 7pm Open Gym
 *   node book-class.mjs --dry-run          # Just find the class, don't book
 *   node book-class.mjs --max-attempts 30  # Retry up to 30 times
 *
 * Environment variables:
 *   GYM_EMAIL    - Login email (default: andrew.mercer@gmail.com)
 *   GYM_PASSWORD - Login password
 */

const BASE_URL = 'https://app.southbank-sc.com';
const DEFAULT_EMAIL = 'andrew.mercer@gmail.com';
const DEFAULT_PASSWORD = 'Kettlebell42!';

// Target: Monday, 19:00 AEST (09:00 UTC)
const TARGET_DAY = 1; // Monday (JS getUTCDay: 0=Sun, 1=Mon)
const TARGET_HOUR_UTC = 9; // 19:00 AEST = 09:00 UTC
const TARGET_CLASS_TYPE = 'open_gym';

const MAX_ATTEMPTS = parseInt(process.env.MAX_ATTEMPTS || '60');
const RETRY_DELAY_MS = 5000;

function log(...args) {
  console.log(`[gym-booking] ${new Date().toISOString()}`, ...args);
}

class GymClient {
  constructor(baseUrl) {
    this.baseUrl = baseUrl;
    this.cookies = '';
  }

  async login(email, password) {
    const res = await fetch(`${this.baseUrl}/login`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ email, password }),
      redirect: 'manual',
    });

    // Extract Set-Cookie headers
    const setCookies = res.headers.getSetCookie?.() || [];
    this.cookies = setCookies.map(c => c.split(';')[0]).join('; ');

    if (!res.ok) {
      const body = await res.text();
      throw new Error(`Login failed (${res.status}): ${body}`);
    }

    const data = await res.json();
    return data.user;
  }

  async graphql(operationName, query, variables = {}) {
    const res = await fetch(`${this.baseUrl}/graphql`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Accept': '*/*',
        'Cookie': this.cookies,
      },
      body: JSON.stringify({ operationName, variables, query }),
    });

    if (!res.ok) {
      const body = await res.text();
      throw new Error(`GraphQL request failed (${res.status}): ${body}`);
    }

    return res.json();
  }

  async getClasses(fromDate, toDate) {
    const data = await this.graphql(
      'Classes',
      `query Classes($from: DateTime!, $to: DateTime!) {
        classes(from: $from, to: $to) {
          id classType startsAt endsAt capacity coachName confirmedCount spotsLeft
        }
      }`,
      { from: fromDate, to: toDate }
    );
    return data.data?.classes || [];
  }

  async createReservation(classInstanceId) {
    const data = await this.graphql(
      'CreateReservation',
      `mutation CreateReservation($classInstanceId: ID!) {
        createReservation(classInstanceId: $classInstanceId) {
          reservation { id status waitlistPosition }
          errorCode
        }
      }`,
      { classInstanceId }
    );
    return data.data?.createReservation;
  }

  async getMyReservations() {
    const data = await this.graphql(
      'MyReservations',
      `query MyReservations {
        myReservations {
          id status waitlistPosition createdAt
          classInstance { id classType startsAt coachName }
        }
      }`
    );
    return data.data?.myReservations || [];
  }
}

function findTargetClass(classes) {
  const now = new Date();
  const candidates = classes.filter(c => {
    if (c.classType !== TARGET_CLASS_TYPE) return false;
    const dt = new Date(c.startsAt);
    return dt > now &&
           dt.getUTCDay() === TARGET_DAY &&
           dt.getUTCHours() === TARGET_HOUR_UTC &&
           dt.getUTCMinutes() === 0;
  });

  if (candidates.length === 0) return null;

  // Sort by date, pick the furthest-out Monday we haven't booked yet
  // (the nearest one is likely already booked from last week's run)
  candidates.sort((a, b) => new Date(a.startsAt) - new Date(b.startsAt));

  return candidates;
}

function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

async function main() {
  const args = process.argv.slice(2);
  const dryRun = args.includes('--dry-run');
  const maxAttempts = (() => {
    const idx = args.indexOf('--max-attempts');
    return idx >= 0 ? parseInt(args[idx + 1]) : MAX_ATTEMPTS;
  })();

  const email = process.env.GYM_EMAIL || DEFAULT_EMAIL;
  const password = process.env.GYM_PASSWORD || DEFAULT_PASSWORD;

  const client = new GymClient(BASE_URL);

  // Step 1: Login
  log('Logging in...');
  const user = await client.login(email, password);
  log(`Logged in as ${user.firstName} ${user.lastName} (${user.membershipType})`);

  // Step 2: Find target class
  const now = new Date();
  const from = now.toISOString();
  const to = new Date(now.getTime() + 14 * 24 * 60 * 60 * 1000).toISOString();

  log('Fetching schedule...');
  const classes = await client.getClasses(from, to);
  const candidates = findTargetClass(classes);

  if (!candidates || candidates.length === 0) {
    log('ERROR: No Monday 7pm Open Gym found in next 14 days');
    process.exit(1);
  }

  log(`Found ${candidates.length} upcoming Monday 7pm Open Gym classes`);

  // Check which ones are already booked
  const reservations = await client.getMyReservations();
  const bookedClassIds = new Set(
    reservations
      .filter(r => r.status === 'confirmed' || r.status === 'waitlisted')
      .map(r => r.classInstance?.id)
      .filter(Boolean)
  );

  // Find the first unbooked candidate
  const target = candidates.find(c => !bookedClassIds.has(c.id));

  if (!target) {
    log('All upcoming Monday 7pm Open Gym classes are already booked/waitlisted!');
    candidates.forEach(c => {
      const dt = new Date(c.startsAt).toLocaleString('en-AU', { timeZone: 'Australia/Brisbane' });
      log(`  ✅ ${dt} AEST - already secured`);
    });
    process.exit(0);
  }

  const classDate = new Date(target.startsAt);
  const localTime = classDate.toLocaleString('en-AU', { timeZone: 'Australia/Brisbane' });
  log(`Target class: ${localTime} AEST`);
  log(`  Coach: ${target.coachName}`);
  log(`  Spots: ${target.spotsLeft}/${target.capacity}`);
  log(`  Class ID: ${target.id}`);

  if (dryRun) {
    log('DRY RUN - would attempt to book this class');
    process.exit(0);
  }

  // Step 3: Book with retry loop
  for (let attempt = 1; attempt <= maxAttempts; attempt++) {
    log(`Booking attempt ${attempt}/${maxAttempts}...`);

    try {
      const result = await client.createReservation(target.id);

      if (result.reservation) {
        const { status, id, waitlistPosition } = result.reservation;

        if (status === 'confirmed') {
          log('✅ SUCCESS! Booked Monday 7pm Open Gym');
          log(`  Reservation ID: ${id}`);
          log(`  Class: ${localTime} AEST with ${target.coachName}`);
          // Output JSON for programmatic consumption
          console.log(JSON.stringify({
            success: true,
            status: 'confirmed',
            reservationId: id,
            classId: target.id,
            classTime: target.startsAt,
            coach: target.coachName,
          }));
          process.exit(0);
        }

        if (status === 'waitlisted') {
          log(`📋 Waitlisted at position ${waitlistPosition}`);
          log(`  Reservation ID: ${id}`);
          console.log(JSON.stringify({
            success: true,
            status: 'waitlisted',
            position: waitlistPosition,
            reservationId: id,
            classId: target.id,
          }));
          process.exit(0);
        }
      }

      if (result.errorCode) {
        if (result.errorCode.includes('NOT_OPEN') || result.errorCode.includes('not_open')) {
          log(`Class not open for booking yet, retrying in ${RETRY_DELAY_MS / 1000}s...`);
          await sleep(RETRY_DELAY_MS);
          continue;
        }

        log(`ERROR: ${result.errorCode}`);
        if (result.errorCode.includes('FULL') || result.errorCode.includes('full')) {
          log('Class is full. The mutation should auto-waitlist.');
        }
        // Retry on other errors too
        await sleep(RETRY_DELAY_MS);
        continue;
      }

      log(`Unexpected result: ${JSON.stringify(result)}`);
      await sleep(RETRY_DELAY_MS);

    } catch (err) {
      log(`Request error: ${err.message}`);
      await sleep(RETRY_DELAY_MS);
    }
  }

  log(`FAILED: Exhausted all ${maxAttempts} attempts`);
  console.log(JSON.stringify({ success: false, error: 'max_attempts_exhausted' }));
  process.exit(1);
}

main().catch(err => {
  log(`Fatal error: ${err.message}`);
  process.exit(1);
});

