    body: JSON.stringify({
      operationName: 'Classes',
      variables: {
        from: new Date(Date.now() + 84*24*60*60*1000).toISOString(),
        to: new Date(Date.now() + 112*24*60*60*1000).toISOString()
      },
      query: 'query Classes($from: DateTime!, $to: DateTime!) { classes(from: $from, to: $to) { id classType startsAt coachName spotsLeft } }'
    })
  })
  .then(r => r.json())
  .then(data => {
    const classes = data.data?.classes || [];
    if (classes.length === 0) return JSON.stringify({ totalReturned: 0, message: 'No more classes beyond 84 days' });

    const monGym = classes.filter(c => {
      if (c.classType !== 'open_gym') return false;
      const dt = new Date(c.startsAt);
      return dt.getUTCDay() === 1 && dt.getUTCHours() === 9;
    });

    // Book them
    return monGym.reduce((chain, cls) =>
      chain.then(results =>
        fetch('https://app.southbank-sc.com/graphql', {
          method: 'POST',
          headers: {'Content-Type': 'application/json', 'Accept': '*/*'},
          body: JSON.stringify({
            operationName: 'CreateReservation',
            variables: { classInstanceId: cls.id },
            query: 'mutation CreateReservation($classInstanceId: ID!) { createReservation(classInstanceId: $classInstanceId) { reservation { id status } errorCode } }'
          })
        })
        .then(r => r.json())
        .then(d => [...results, {
          date: new Date(cls.startsAt).toLocaleDateString('en-AU', {timeZone:'Australia/Brisbane', weekday:'long', day:'numeric', month:'short'}),
          coach: cls.coachName,
          status: d.data.createReservation.reservation?.status || d.data.createReservation.errorCode
        }])
      ), Promise.resolve([])
    ).then(r => JSON.stringify({ totalInWindow: classes.length, booked: r }, null, 2));
  });
}

